\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{pgfplots}
\usepackage{pgffor}
\pgfplotsset{compat=1.18}
\pagestyle{empty}

% ── IMF-Inspired Color Theme ──
\definecolor{primary}{HTML}{002244}     % IMF deep navy
\definecolor{secondary}{HTML}{475569}   % slate gray
\definecolor{accent}{HTML}{D97706}      % amber (risk highlight)
\definecolor{darkaccent}{HTML}{B45309} % darker amber
\definecolor{bgposter}{HTML}{F1F5F9}    % cool light gray background
\definecolor{redbg}{HTML}{FEF2F2}      % warm red tint for redcard
\definecolor{bluebg}{HTML}{EFF6FF}      % cool blue tint for bluecard
\definecolor{darkbg}{HTML}{F8FAFC}     % near-white for darkcard
\definecolor{darktitlebg}{HTML}{E2E8F0}
\definecolor{redtitlebg}{HTML}{FEE2E2}
\definecolor{bluetitlebg}{HTML}{DBEAFE}
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{475569}
\definecolor{amberbg}{HTML}{FFFBEB}
\definecolor{ambertitlebg}{HTML}{FDE68A}
\definecolor{stathighlight}{HTML}{FFF7ED}
\definecolor{statborder}{HTML}{FED7AA}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Subheader command ──
\newcommand{\subheader}[2]{\begin{minipage}{#1\linewidth}\centering
  {\fontsize{36}{44}\selectfont\bfseries\color{primary}#2}\end{minipage}\\[2mm]}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.2},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{74}{90}\selectfont\bfseries Global Economy in the Shadow of War}\\[10pt]
  {\fontsize{34}{42}\selectfont\color{white!85} IMF World Economic Outlook Trends 2024--2026}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{white!60} IMF-World Bank Annual Meetings Research Symposium}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=5pt, bottom=5pt,
  valign=center, borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{74}\selectfont\bfseries\color{primary} 3.0\%}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global Growth 2025}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray} WEO Jul 2025}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{74}\selectfont\bfseries\color{primary} 3.3\%}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global Growth 2026}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray} WEO Jan 2026}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!35}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{74}\selectfont\bfseries\color{primary} 8}\\[3pt]
      {\fontsize{24}{30}\selectfont\color{textdark} WEO Editions Reviewed}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Jul 2024 -- Apr 2026}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{accent!40}{amberbg}{\parbox{0.86\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{66}\selectfont\bfseries\color{accent} Tilted to}\\[3pt]
      {\fontsize{52}{66}\selectfont\bfseries\color{accent} the Downside}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{darkaccent} Risk Balance (all editions)}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ GROWTH TRAJECTORY ══
\posterbox[darkcard, title={Global Growth Projections: A Narrow Band of Mediocrity}
]{name=growth, column=1, span=2, between=row6 and row12}{
  \fontsize{32}{40}\selectfont
  \begin{tikzpicture}[trim axis left, trim axis right]
    \begin{axis}[
      width=0.96\linewidth,
      height=11cm,
      xtick={1,2,3,4,5,6,7,8},
      xticklabels={Jul '24, Oct '24, Jan '25, Apr '25, Jul '25, Oct '25, Jan '26, Apr '26},
      xticklabel style={font=\fontsize{22}{28}\selectfont, rotate=35, anchor=north east, text height=5pt},
      ymin=2.5, ymax=3.8,
      ylabel={Growth Rate (\%), centered},
      ylabel style={font=\fontsize{24}{30}\selectfont, color=textdark},
      ytick={2.5,2.75,3.0,3.25,3.5,3.75,3.8},
      yticklabels={2.5,2.75,3.0,3.25,3.5,3.75,---},
      yticklabel style={font=\fontsize{22}{28}\selectfont, color=textgray},
      grid=both,
      grid style={gray!30, line width=0.5pt},
      axis lines=left,
      line width=2.5pt,
      mark size=7pt,
      every node near coord/.style={font=\fontsize{20}{26}\selectfont, color=textdark, anchor=south},
    ]
      \addplot[color=primary, line width=2.5pt, mark=*, mark options={fill=primary}] coordinates {
        (1,3.2) (2,3.2) (3,3.3) (4,3.1) (5,3.0) (6,2.9) (7,3.3) (8,2.9)
      };
      \addplot[color=accent, line width=2pt, mark=square*, mark options={fill=accent}] coordinates {
        (1,3.3) (2,3.3) (3,3.3) (4,3.1) (5,3.1) (6,2.9) (7,3.2) (8,2.8)
      };
      \draw[dashed, gray!60, line width=1.5pt] (axis cs:1,3.8) -- (axis cs:8,3.8)
        node[midway, above, font=\fontsize{20}{26}\selectfont, color=gray!60]{Pre-pandemic avg (3.8\%)};
    \end{axis}
  \end{tikzpicture}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Blue = 2024/25 forecasts, Amber = 2025/26 forecasts. Dashed line = pre-pandemic average.}}
}

% ══ KEY RISKS ══
\posterbox[ambercard, title={Dominant Downside Risks}
]{name=risks, column=3, between=row6 and row10}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Tariff escalation:} Retaliatory measures from 2025 onward; front-loading masks near-term damage
    \item \textbf{Geopolitical tensions:} Middle East conflict, broader security concerns, shadow of war
    \item \textbf{Tech re-evaluation:} AI and tech investment expectations face correction risk
    \item \textbf{Sticky services inflation:} US return-to-target slower than peer economies
  \end{itemize}
  \vspace{2mm}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{darkaccent}\bfseries
    Risk balance: Tilted to downside $\rightarrow$ \textbf{across all 8 WEO editions}}}
}

% ══ INFLATION DYNAMICS ══
\posterbox[bluecard, title={Inflation Outlook and Monetary Policy}
]{name=inflation, column=1, between=row12 and row16}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Global headline inflation declining, enabling monetary easing
    \item US inflation slower to return-to-target than peer economies
    \item Services inflation particularly sticky; slows disinflation
    \item Renewed pressures by Apr 2026: defense spending, supply disruptions
  \end{itemize}
  \vspace{2mm}
  \colorbox{accent!18}{\parbox{0.92\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textdark}
    "Policy pivot" underway globally $\rightarrow$ uneven path, risks remain}}
}

% ══ POLICY EVOLUTION ══
\posterbox[redcard, title={Evolving Policy Priorities}
]{name=policy, column=2, between=row12 and row17}{
  \fontsize{32}{40}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item[] \textbf{Mid-2024:} Carefully manage disinflation; begin monetary easing
    \item[] \textbf{Late 2024:} Pivot monetary policy; ensure fiscal sustainability
    \item[] \textbf{Early 2025:} Rebuild fiscal buffers; address demographic and gender gaps
    \item[] \textbf{Mid-2025:} Restore confidence and predictability amid tariff uncertainty
    \item[] \textbf{Late 2025:} Strengthen policy frameworks; cautious industrial policy
    \item[] \textbf{Early 2026:} Agile policy; manage defense-spending trade-offs
  \end{itemize}
}

% ══ THEMATIC FOCUS ══
\posterbox[bluecard, title={Special Analytical Themes}
]{name=themes, column=3, between=row10 and row13}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Monetary policy role in global disinflation
    \item Social acceptability of structural reforms
    \item Industrial policy: effectiveness vs. fiscal cost
    \item Aging populations, gender disparities, migrant skill alignment
  \end{itemize}
}

% ══ KEY TAKEAWAYS ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=takeaways, column=1, span=3, between=row17 and bottom}{
  {\fontsize{38}{46}\selectfont\bfseries\color{white} Key Takeaways}\\[6pt]
  \begin{minipage}[t]{0.31\linewidth}\centering
    {\fontsize{30}{38}\selectfont\bfseries\color{white!90} Narrow growth band:}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{white!75} Global growth stuck at 3.0--3.3\% for two years}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.31\linewidth}\centering
    {\fontsize{30}{38}\selectfont\bfseries\color{white!90} Persistent fragility:}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{white!75} Risks tilted downside across all 8 WEO editions}
  \end{minipage}\hfill
  {\begin{minipage}[t]{0.31\linewidth}\centering
    {\fontsize{30}{38}\selectfont\bfseries\color{white!90} Policy shift:}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{white!75} From buffers $\rightarrow$ structural reform $\rightarrow$ defense trade-offs}
  \end{minipage}}
}

\end{tcbposter}
\end{document}

